{"command":"python3 -c '
import pygments, pygments.lexers

def get_chroma_tokens(code, lexer_name):
    lexer = pygments.lexers.get_lexer_by_name(lexer_name)
    tokens = []
    for token_type, value in lexer.get_tokens(code):
        if not value:
            continue
        # Convert Token.Keyword.Type -> "KeywordType"
        t_str = str(token_type)
        if t_str.startswith("Token."):
            t_name = t_str[6:].replace(".", "")
        else:
            t_name = t_str.replace(".", "")
        if t_name == "TextWhitespace":
            t_name = "Text"
        if tokens and tokens[-1][0] == t_name:
            tokens[-1] = (t_name, tokens[-1][1] + value)
        else:
            tokens.append((t_name, value))
    return tokens

print(get_chroma_tokens("int main() { return 0; }\n", "c"))
'"}

