{"command":"python3 -c '
import subprocess, re

res = subprocess.run(["./executable", "--html-styles", "-s", "github"], capture_output=True, text=True)
css = res.stdout

style_dict = {}
for line in css.splitlines():
    m = re.search(r"/\*\s*(.*?)\s*\*/\s*\.chroma\s*\.(\w+)\s*\{(.*?)\}", line)
    if m:
        token_name, cls, rules = m.groups()
        fg = None
        bg = None
        bold = "font-weight: bold" in rules
        italic = "font-style: italic" in rules
        underline = "text-decoration: underline" in rules

        m_fg = re.search(r"(?:^|;\s*)color:\s*(#[0-9a-fA-F]+)", rules)
        if m_fg: fg = m_fg.group(1)
        m_bg = re.search(r"background-color:\s*(#[0-9a-fA-F]+)", rules)
        if m_bg: bg = m_bg.group(1)

        style_dict[cls] = {"name": token_name, "fg": fg, "bg": bg, "bold": bold, "italic": italic, "underline": underline}

print(f"Extracted {len(style_dict)} classes for github style:")
print(list(style_dict.items())[:5])
'"}

