{"command":"python3 -c '
import subprocess, re, json

with open("/tmp/orig_list.txt") as f:
    text = f.read()

styles_line = [l for l in text.splitlines() if l.startswith("styles:")][0]
styles = styles_line.split()[1:]

styles_db = {}

for s in styles:
    if s == "swapoff":
        continue
    res = subprocess.run(["./executable", "--html-styles", "-s", s], capture_output=True, text=True)
    if res.returncode != 0:
        continue
    css = res.stdout

    bg = None
    m_bg = re.search(r"/\*\s*Background\s*\*/\s*\.bg\s*\{(.*?)\}", css)
    if m_bg:
        rules = m_bg.group(1)
        m_c = re.search(r"(?:^|;\s*)color:\s*(#[0-9a-fA-F]+)", rules)
        m_b = re.search(r"background-color:\s*(#[0-9a-fA-F]+)", rules)
        bg = {"fg": m_c.group(1) if m_c else None, "bg": m_b.group(1) if m_b else None}

    tokens = {}
    for line in css.splitlines():
        m = re.search(r"/\*\s*(.*?)\s*\*/\s*\.chroma\s*\.(\w+)\s*\{(.*?)\}", line)
        if m:
            token_name, cls, rules = m.groups()
            fg = None
            bg_col = None
            bold = "font-weight: bold" in rules
            italic = "font-style: italic" in rules
            underline = "text-decoration: underline" in rules

            m_fg = re.search(r"(?:^|;\s*)color:\s*(#[0-9a-fA-F]+)", rules)
            if m_fg: fg = m_fg.group(1)
            m_bg = re.search(r"background-color:\s*(#[0-9a-fA-F]+)", rules)
            if m_bg: bg_col = m_bg.group(1)

            tokens[cls] = {"name": token_name, "fg": fg, "bg": bg_col, "bold": bold, "italic": italic, "underline": underline}

    styles_db[s] = {
        "css": css,
        "bg": bg,
        "tokens": tokens
    }

print(f"Successfully generated database for {len(styles_db)} styles!")
with open("/tmp/styles_db.json", "w") as f:
    json.dump(styles_db, f)
'"}

