import json

with open("/tmp/orig_list.txt") as f:
    text = f.read()

lexers_part = text.split("styles:")[0]

lexers_db = []
current_lexer = None

for line in lexers_part.splitlines():
    if line.startswith("lexers:"):
        continue
    if not line.strip():
        continue
    if line.startswith("  ") and not line.startswith("    "):
        if current_lexer:
            lexers_db.append(current_lexer)
        current_lexer = {"name": line.strip(), "aliases": [], "filenames": [], "mimetypes": []}
    elif line.startswith("    aliases:"):
        current_lexer["aliases"] = line.replace("    aliases:", "").strip().split()
    elif line.startswith("    filenames:"):
        current_lexer["filenames"] = line.replace("    filenames:", "").strip().split()
    elif line.startswith("    mimetypes:"):
        current_lexer["mimetypes"] = line.replace("    mimetypes:", "").strip().split()

if current_lexer:
    lexers_db.append(current_lexer)

print(f"Extracted {len(lexers_db)} lexers!")
print("First 3:", lexers_db[:3])
with open("/tmp/lexers_db.json", "w") as f:
    json.dump(lexers_db, f)
'"}

