{"command":"python3 -c '
import json, pygments.lexers

with open("/tmp/lexers_db.json") as f:
    lexers_db = json.load(f)

found_count = 0
missing_lexers = []

for l in lexers_db:
    found = False
    # try name
    try:
        pygments.lexers.get_lexer_by_name(l["name"])
        found = True
    except Exception:
        pass

    if not found:
        # try aliases
        for alias in l["aliases"]:
            try:
                pygments.lexers.get_lexer_by_name(alias)
                found = True
                break
            except Exception:
                pass

    if not found:
        # try filenames
        for fn in l["filenames"]:
            fn_clean = fn.replace("*", "test")
            try:
                pygments.lexers.get_lexer_for_filename(fn_clean)
                found = True
                break
            except Exception:
                pass

    if found:
        found_count += 1
    else:
        missing_lexers.append(l["name"])

print(f"Pygments found {found_count} / {len(lexers_db)} lexers!")
print(f"Missing lexers ({len(missing_lexers)}): {missing_lexers}")
'"}

