        for m in l["mimetypes"]:
            LEXER_MAP[m.lower()] = plex

# Build 256 Color Palette
def get_256_palette():
    palette = []
    ansi16 = [
        (0,0,0), (128,0,0), (0,128,0), (128,128,0), (0,0,128), (128,0,128), (0,128,128), (192,192,192),
        (128,128,128), (255,0,0), (0,255,0), (255,255,0), (0,0,255), (255,0,255), (0,255,255), (255,255,255)
    ]
    palette.extend(ansi16)
    vals = [0, 95, 135, 175, 215, 255]
    for r in vals:
        for g in vals:
            for b in vals:
                palette.append((r, g, b))
    for i in range(24):
        v = 8 + i * 10
        palette.append((v, v, v))
    return palette

PALETTE_256 = get_256_palette()

def hex_to_rgb(h):
    if not h:
        return None
    h = h.lstrip("#")
    if len(h) == 3:
        h = "".join(c*2 for c in h)
    return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

def rgb_to_256(r, g, b):
    best_i = 0
    best_dist = 100000000
    for i, (pr, pg, pb) in enumerate(PALETTE_256):
        d = (r - pr)**2 + (g - pg)**2 + (b - pb)**2
        if d < best_dist:
            best_dist = d
            best_i = i
    return best_i

def rgb_to_16(r, g, b):
    best_i = 0
    best_dist = 100000000
    for i in range(16):
        pr, pg, pb = PALETTE_256[i]
        d = (r - pr)**2 + (g - pg)**2 + (b - pb)**2
        if d < best_dist:
            best_dist = d
            best_i = i
    return best_i

