        elif arg.startswith("--html-highlight="):
            html_highlight = arg.split("=", 1)[1]
        elif arg == "--html-highlight":
            if i + 1 < len(args):
                i += 1
                html_highlight = args[i]
            else:
                sys.stderr.write(f'{app_name}: error: --html-highlight: expected string value but got "EOL" (<EOL>)\n')
                sys.exit(80)
        elif arg.startswith("--html-highlight-style="):
            html_highlight_style = arg.split("=", 1)[1]
        elif arg == "--html-highlight-style":
            if i + 1 < len(args):
                i += 1
                html_highlight_style = args[i]
            else:
                sys.stderr.write(f'{app_name}: error: --html-highlight-style: expected string value but got "EOL" (<EOL>)\n')
                sys.exit(80)
        elif arg.startswith("--html-base-line="):
            try:
                html_base_line = int(arg.split("=", 1)[1])
            except ValueError:
                v = arg.split("=", 1)[1]
                sys.stderr.write(f'{app_name}: error: --html-base-line: expected int value but got "{v}"\n')
                sys.exit(80)
        elif arg == "--html-base-line":
            if i + 1 < len(args):
                i += 1
                try:
                    html_base_line = int(args[i])
                except ValueError:
                    sys.stderr.write(f'{app_name}: error: --html-base-line: expected int value but got "{args[i]}"\n')
                    sys.exit(80)
            else:
                sys.stderr.write(f'{app_name}: error: --html-base-line: expected int value but got "EOL" (<EOL>)\n')
                sys.exit(80)
        elif arg.startswith("-"):
            if arg.startswith("--"):
                sys.stderr.write(f'{app_name}: error: unknown flag {arg}\n')
            else:
                sys.stderr.write(f'{app_name}: error: unknown flag {arg}, did you mean one of "-h", "-l", "-s", "-f"?\n')
            sys.exit(80)
        else:
            if flags_started_after_pos:
                sys.stderr.write(f'{app_name}: error: unexpected argument {arg}\n')
                sys.exit(80)
            files.append(arg)
        i += 1
        if files and not flags_started_after_pos:
            if i < len(args) and args[i].startswith("-"):
                flags_started_after_pos = True

    # Validate files
    for fpath in files:
        try:
            os.stat(fpath)
        except OSError:
            abs_path = os.path.abspath(fpath)
            sys.stderr.write(f"{app_name}: error: [<files> ...]: stat {abs_path}: no such file or directory\n")
            sys.exit(80)

    # Determine Formatter
    if json_flag:
        formatter = "json"
    elif html_flag:
        formatter = "html"
    elif svg_flag:
        formatter = "svg"

    # Style
    if style not in STYLES_DB:
        try:
            with open(style, "r") as f:
                pass
        except OSError:
            sys.stderr.write(f"{app_name}: error: open {style}: no such file or directory\n")
            sys.exit(1)

    style_data = STYLES_DB.get(style, {})

    if html_styles or html_all_styles:
        if style_data and "css" in style_data:
            sys.stdout.write(style_data["css"])
        sys.exit(0)

    # Read inputs
    inputs = []
    if files:
        for fpath in files:
            with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                inputs.append((fpath, f.read()))
    else:
        content = sys.stdin.read()
        inputs.append((filename or "", content))

    # Process each input
    for fpath, code in inputs:
        # Lexer resolution
        plex = None
        is_fallback = False

        if lexer != "autodetect":
            lkey = lexer.lower()
            if lkey in LEXER_MAP:
                plex = LEXER_MAP[lkey]
            else:
                try:
                    plex = pygments.lexers.get_lexer_by_name(lexer)
                except Exception:
                    pass
            if not plex:
                is_fallback = True
        else:
            fname = filename or fpath
            if fname:
                ext = os.path.splitext(fname)[1].lower()
                basename = os.path.basename(fname).lower()
                if ext in LEXER_MAP:
                    plex = LEXER_MAP[ext]
                elif basename in LEXER_MAP:
                    plex = LEXER_MAP[basename]
                else:
                    try:
                        plex = pygments.lexers.get_lexer_for_filename(fname)
                    except Exception:
                        pass
            if not plex and code:
                try:
                    plex = pygments.lexers.guess_lexer(code[:1024])
                except Exception:
                    pass
            if not plex:
                is_fallback = True

        if is_fallback:
            if fail:
                sys.exit(1)
            plex = pygments.lexers.TextLexer()

        tokens = get_chroma_tokens(code, plex)

        if check:
            has_err = any(t[0] == "Error" for t in tokens)
            if has_err:
                sys.exit(1)

        # Output formatting
        if formatter == "json":
            out_lines = ["["]
            for idx, (t_name, val) in enumerate(tokens):
                t_json = json.dumps(t_name)
                v_json = json.dumps(val)
                comma = "," if idx < len(tokens) - 1 else ""
                out_lines.append(f'  {{"type":{t_json},"value":{v_json}}}{comma}')
            out_lines.append("]\n")
            sys.stdout.write("\n".join(out_lines))

        elif formatter == "tokens":
            out_lines = []
            for t_name, val in tokens:
                v_json = json.dumps(val)
                out_lines.append(f'&Token{{{t_name}}, {v_json}}}')
            sys.stdout.write("\n".join(out_lines) + "\n")

        elif formatter == "noop":
            sys.stdout.write(code)

        elif formatter.startswith("terminal"):
            out_parts = []
            style_tokens = style_data.get("tokens", {})
            for t_name, val in tokens:
                cls = CLS_MAP.get(t_name, "")
                info = style_tokens.get(cls) if cls else None
                if info and (info["fg"] or info["bg"] or info["bold"] or info["italic"] or info["underline"]):
                    codes = []
                    if info["bold"]: codes.append("1")
                    if info["italic"]: codes.append("3")
                    if info["underline"]: codes.append("4")
                    fg_rgb = hex_to_rgb(info["fg"]) if info["fg"] else None
                    bg_rgb = hex_to_rgb(info["bg"]) if info["bg"] else None

                    if formatter in ("terminal", "terminal8"):
                        if fg_rgb:
                            c16 = rgb_to_16(*fg_rgb)
                            if c16 >= 8:
                                if "1" not in codes: codes.append("1")
                                codes.append(str(30 + (c16 - 8)))
                            else:
                                codes.append(str(30 + c16))
                        if bg_rgb:
                            c16 = rgb_to_16(*bg_rgb)
                            codes.append(str(40 + (c16 % 8)))
                    elif formatter == "terminal16":
                        if fg_rgb:
                            c16 = rgb_to_16(*fg_rgb)
                            codes.append(str(90 + (c16 - 8)) if c16 >= 8 else str(30 + c16))
                        if bg_rgb:
                            c16 = rgb_to_16(*bg_rgb)
                            codes.append(str(100 + (c16 - 8)) if c16 >= 8 else str(40 + c16))
                    elif formatter == "terminal256":
                        if fg_rgb:
                            c256 = rgb_to_256(*fg_rgb)
                            codes.append(f"38;5;{c256}")
                        if bg_rgb:
                            c256 = rgb_to_256(*bg_rgb)
                            codes.append(f"48;5;{c256}")
                    elif formatter == "terminal16m":
                        if fg_rgb:
                            r, g, b = fg_rgb
                            codes.append(f"38;2;{r};{g};{b}")
                        if bg_rgb:
                            r, g, b = bg_rgb
                            codes.append(f"48;2;{r};{g};{b}")

                    prefix_seq = f"\x1b[{';'.join(codes)}m" if codes else ""
                    out_parts.append(f"{prefix_seq}{val}\x1b[0m")
                else:
                    out_parts.append(val)
            sys.stdout.write("".join(out_parts))

        elif formatter == "html":
            # Tab width expansion
            if html_tab_width > 0:
                code_text = code.replace("\t", " " * html_tab_width)
            else:
                code_text = code

            # Split code into lines
            raw_lines = code_text.split("\n")
            if raw_lines and raw_lines[-1] == "":
                raw_lines = raw_lines[:-1]

            highlight_set = parse_highlight_lines(html_highlight)
            style_css = style_data.get("css", "")
            bg_info = style_data.get("bg", {}) or {}

            # Generate line HTMLs
            line_htmls = []
            curr_line_num = html_base_line

            for line_idx, line_raw in enumerate(raw_lines):
                # re-tokenize line
                line_tokens = get_chroma_tokens(line_raw, plex)
                spans = []
                for t_name, val in line_tokens:
                    c = CLS_MAP.get(t_name, "")
                    e_val = html.escape(val)
                    if html_inline_styles:
                        info = style_data.get("tokens", {}).get(c) if c else None
                        if info:
                            rules = []
                            if info["fg"]: rules.append(f"color:{info['fg']}")
                            if info["bg"]: rules.append(f"background-color:{info['bg']}")
                            if info["bold"]: rules.append("font-weight:bold")
                            if info["italic"]: rules.append("font-style:italic")
                            if info["underline"]: rules.append("text-decoration:underline")
                            if rules:
                                spans.append(f'<span style="{";".join(rules)}">{e_val}</span>')
                            else:
                                spans.append(e_val)
                        else:
                            spans.append(e_val)
                    else:
                        if c and t_name != "Text":
                            spans.append(f'<span class="{html_prefix}{c}">{e_val}</span>')
                        else:
                            spans.append(e_val)

                inner_code = "".join(spans)
                line_hl = (curr_line_num in highlight_set)
                line_class = f"{html_prefix}line {html_prefix}hl" if line_hl else f"{html_prefix}line"

                ln_span = ""
                if html_lines and not html_lines_table:
                    if html_linkable_lines:
                        ln_span = f'<span class="{html_prefix}ln" id="L{curr_line_num}"><a class="{html_prefix}lnlinks" href="#L{curr_line_num}">{curr_line_num}</a></span>'
                    else:
                        ln_span = f'<span class="{html_prefix}ln">{curr_line_num}</span>'

                line_htmls.append(f'<span class="{line_class}">{ln_span}<span class="{html_prefix}cl">{inner_code}</span>\n</span>')
                curr_line_num += 1

            body_content = "".join(line_htmls)

            if html_lines_table and html_lines:
                ln_pre = []
                num = html_base_line
                for _ in raw_lines:
                    ln_pre.append(f'<span class="{html_prefix}lnt">{num}\n</span>')
                    num += 1
                table_html = f'<div class="{html_prefix}chroma">\n<table class="{html_prefix}lntable"><tr><td class="{html_prefix}lntd">\n<pre class="{html_prefix}chroma">{"".join(ln_pre)}</pre></td>\n<td class="{html_prefix}lntd">\n<pre class="{html_prefix}chroma"><code>{body_content}</code></pre></td></tr></table>\n</div>\n'
                snippet = table_html
            else:
                if html_prevent_surrounding_pre:
                    snippet = body_content
                else:
                    snippet = f'<pre class="{html_prefix}chroma"><code>{body_content}</code></pre>'

            if html_only:
                sys.stdout.write(snippet)
            else:
                fg_col = bg_info.get("fg") or ""
                bg_col = bg_info.get("bg") or ""
                doc = f'<html>\n<style type="text/css">\n{style_css}\nbody {{ color:{fg_col};background-color:{bg_col};; }}\n</style><body class="bg">\n{snippet}\n</body>\n</html>\n'
                sys.stdout.write(doc)

        elif formatter == "svg":
            style_tokens = style_data.get("tokens", {})
            bg_info = style_data.get("bg", {}) or {}
            bg_hex = bg_info.get("bg") or "#272822"
            fg_hex = bg_info.get("fg") or "#f8f8f2"

            svg_lines = []
            for t_name, val in tokens:
                cls = CLS_MAP.get(t_name, "")
                info = style_tokens.get(cls) if cls else None
                e_val = html.escape(val).replace(" ", "&#160;")
                if info and info["fg"]:
                    svg_lines.append(f'<tspan fill="{info["fg"]}">{e_val}</tspan>')
                else:
                    svg_lines.append(e_val)

            content_str = "".join(svg_lines)
            width_px = len(code) * 8 + 20
            height_px = 43

            svg_doc = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.0//EN" "http://www.w3.org/TR/2001/REC-SVG-20010904/DTD/svg10.dtd">
<svg width="{width_px}px" height="{height_px}px" xmlns="http://www.w3.org/2000/svg">
<style>
@font-face {{
	font-family: 'Liberation Mono';
	src: url(data:application/x-font-woff;charset=utf-8;base64,) format('woff');
	font-weight: normal;
	font-style: normal;
}}
</style><rect width="100%" height="100%" fill="{bg_hex}"/>
<g font-family="Liberation Mono" font-size="14px" fill="{fg_hex}">
<text x="0" y="1.200000em" xml:space="preserve">{content_str}
</text>
</g>
</svg>
"""
            sys.stdout.write(svg_doc)

if __name__ == "__main__":
    main()
