Select lexer and style:
  -l, --lexer="autodetect"    Lexer to use when formatting or path to an XML
                              file to load.
  -s, --style="swapoff"       Style to use for formatting or path to an XML file
                              to load.

Output format:
  -f, --formatter="terminal"    Formatter to use.
      --json                    Convenience flag to use JSON formatter.
      --html                    Convenience flag to use HTML formatter.
      --svg                     Convenience flag to use SVG formatter.

HTML formatter options:
  --html-prefix=PREFIX             HTML CSS class prefix.
  --html-styles                    Output HTML CSS styles.
  --html-all-styles                Output all HTML CSS styles, including
                                   redundant ones.
  --html-only                      Output HTML fragment.
  --html-inline-styles             Output HTML with inline styles (no classes).
  --html-tab-width=8               Set the HTML tab width.
  --html-lines                     Include line numbers in output.
  --html-lines-table               Split line numbers and code in a HTML table
  --html-lines-style=STRING        Style for line numbers.
  --html-highlight=N[:M][,...]     Highlight these lines.
  --html-highlight-style=STRING    Style used for highlighting lines.
  --html-base-line=1               Base line number.
  --html-prevent-surrounding-pre
                                   Prevent the surrounding pre tag.
  --html-linkable-lines            Make the line numbers linkable and be a link
                                   to themselves.
"""
    sys.stdout.write(help_text)

def print_list():
    lines = ["lexers:"]
    for l in LEXERS_DB:
        name = l["name"]
        lines.append(f"  {name}")
        if l["aliases"]:
            a = " ".join(l["aliases"])
            lines.append(f"    aliases: {a}")
        if l["filenames"]:
            fn = " ".join(l["filenames"])
            lines.append(f"    filenames: {fn}")
        if l["mimetypes"]:
            m = " ".join(l["mimetypes"])
            lines.append(f"    mimetypes: {m}")
    lines.append("")
    styles = "abap algol algol_nu arduino ashen aura-theme-dark aura-theme-dark-soft autumn average base16-snazzy borland bw catppuccin-frappe catppuccin-latte catppuccin-macchiato catppuccin-mocha colorful darcula doom-one doom-one2 dracula emacs evergarden friendly fruity github github-dark gruvbox gruvbox-light hr_high_contrast hrdark igor kanagawa-dragon kanagawa-lotus kanagawa-wave lovelace manni modus-operandi modus-vivendi monokai monokailight murphy native nord nordic onedark onesenterprise paraiso-dark paraiso-light pastie perldoc pygments rainbow_dash rose-pine rose-pine-dawn rose-pine-moon rpgle rrt solarized-dark solarized-dark256 solarized-light swapoff tango tokyonight-day tokyonight-moon tokyonight-night tokyonight-storm trac vim vs vulcan witchhazel xcode xcode-dark"
    formatters = "html json noop svg terminal terminal16 terminal16m terminal256 terminal8 tokens"
    lines.append(f"styles: {styles}")
    lines.append(f"formatters: {formatters}")
    sys.stdout.write("\n".join(lines) + "\n")

# Build Lexer Lookup Map
LEXER_MAP = {}
for l in LEXERS_DB:
    lname = l["name"]
    plex = None
    try:
        plex = pygments.lexers.get_lexer_by_name(lname)
    except Exception:
        for alias in l["aliases"]:
            try:
                plex = pygments.lexers.get_lexer_by_name(alias)
                break
            except Exception:
                pass
    if plex:
        LEXER_MAP[lname.lower()] = plex
        for a in l["aliases"]:
            LEXER_MAP[a.lower()] = plex
        for fn in l["filenames"]:
            LEXER_MAP[fn.lower()] = plex
        for m in l["mimetypes"]:
            LEXER_MAP[m.lower()] = plex

# Build 256 Color Palette
def get_256_palette():
    palette = []
    ansi16 = [
        (0,0,0), (128,0,0), (0,128,0), (128,128,0), (0,0,128), (128,0,128), (0,128,128), (192,192,192),
        (128,128,128), (255,0,0), (0,255,0), (255,255,0), (0,0,255), (255,0,255), (0,255,255), (255,255,255)
    ]
    palette.extend(ansi16)
    vals = [0, 95, 135, 175, 215, 255]
    for r in vals:
        for g in vals:
            for b in vals:
                palette.append((r, g, b))
    for i in range(24):
        v = 8 + i * 10
        palette.append((v, v, v))
    return palette

PALETTE_256 = get_256_palette()

def hex_to_rgb(h):
    if not h:
        return None
    h = h.lstrip("#")
    if len(h) == 3:
        h = "".join(c*2 for c in h)
    return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

def rgb_to_256(r, g, b):
    best_i = 0
    best_dist = 100000000
    for i, (pr, pg, pb) in enumerate(PALETTE_256):
        d = (r - pr)**2 + (g - pg)**2 + (b - pb)**2
        if d < best_dist:
            best_dist = d
            best_i = i
    return best_i

def rgb_to_16(r, g, b):
    best_i = 0
    best_dist = 100000000
    for i in range(16):
        pr, pg, pb = PALETTE_256[i]
        d = (r - pr)**2 + (g - pg)**2 + (b - pb)**2
        if d < best_dist:
            best_dist = d
            best_i = i
    return best_i

CLS_MAP = {
    "Keyword": "k", "KeywordConstant": "kc", "KeywordDeclaration": "kd", "KeywordNamespace": "kn",
    "KeywordPseudo": "kp", "KeywordReserved": "kr", "KeywordType": "kt",
    "Name": "n", "NameAttribute": "na", "NameClass": "nc", "NameConstant": "no", "NameDecorator": "nd",
    "NameException": "ne", "NameOther": "nx", "NameTag": "nt", "NameEntity": "ni", "NameLabel": "nl",
    "NameNamespace": "nn", "NameBuiltin": "nb", "NameBuiltinPseudo": "bp", "NameVariable": "nv",
    "NameVariableClass": "vc", "NameVariableGlobal": "vg", "NameVariableInstance": "vi", "NameVariableMagic": "vm",
    "NameFunction": "nf", "NameFunctionMagic": "fm",
    "Literal": "l", "LiteralDate": "ld", "LiteralString": "s", "LiteralStringAffix": "sa",
    "LiteralStringBacktick": "sb", "LiteralStringChar": "sc", "LiteralStringDelimiter": "dl",
    "LiteralStringDoc": "sd", "LiteralStringDouble": "s2", "LiteralStringEscape": "se",
    "LiteralStringHeredoc": "sh", "LiteralStringInterpol": "si", "LiteralStringOther": "sx",
    "LiteralStringRegex": "sr", "LiteralStringSingle": "s1", "LiteralStringSymbol": "ss",
    "LiteralNumber": "m", "LiteralNumberBin": "mb", "LiteralNumberFloat": "mf", "LiteralNumberHex": "mh",
    "LiteralNumberInteger": "mi", "LiteralNumberIntegerLong": "il", "LiteralNumberOct": "mo",
    "Operator": "o", "OperatorWord": "ow", "OperatorReserved": "or",
    "Punctuation": "p",
    "Comment": "c", "CommentHashbang": "ch", "CommentMultiline": "cm", "CommentSingle": "c1",
    "CommentSpecial": "cs", "CommentPreproc": "cp", "CommentPreprocFile": "cpf",
    "GenericDeleted": "gd", "GenericEmph": "ge", "GenericInserted": "gi", "GenericOutput": "go",
    "GenericStrong": "gs", "GenericSubheading": "gu", "GenericUnderline": "gl",
    "Error": "err", "TextWhitespace": "w"
}

def get_chroma_tokens(code, plex):
    raw_tokens = plex.get_tokens(code)
    tokens = []
    for token_type, value in raw_tokens:
        if not value:
            continue
        t_str = str(token_type)
        if t_str.startswith("Token."):
            t_name = t_str[6:].replace(".", "")
        else:
            t_name = t_str.replace(".", "")
        if t_name == "TextWhitespace":
            t_name = "Text"
        if tokens and tokens[-1][0] == t_name:
            tokens[-1] = (t_name, tokens[-1][1] + value)
        else:
            tokens.append((t_name, value))
    return tokens

def parse_highlight_lines(s):
    lines = set()
    if not s:
        return lines
    for part in s.split(","):
        part = part.strip()
        if ":" in part:
            try:
                start, end = part.split(":", 1)
                lines.update(range(int(start), int(end) + 1))
            except ValueError:
                pass
        elif part:
            try:
                lines.add(int(part))
            except ValueError:
                pass
    return lines

def main():
    app_name = os.path.basename(sys.argv[0])
    fail = (app_name == ".lessfilter" or app_name.endswith(".lessfilter"))
    lexer = "autodetect"
    style = "swapoff"
    formatter = "terminal"
    unbuffered = False
    trace = False
    check = False
    filename = ""

    json_flag = False
    html_flag = False
    svg_flag = False

    html_prefix = ""
    html_styles = False
    html_all_styles = False
    html_only = False
    html_inline_styles = False
    html_tab_width = 8
    html_lines = False
    html_lines_table = False
    html_lines_style = ""
    html_highlight = ""
    html_highlight_style = ""
    html_base_line = 1
    html_prevent_surrounding_pre = False
    html_linkable_lines = False

    files = []

    args = sys.argv[1:]
    i = 0
    flags_started_after_pos = False

    while i < len(args):
        arg = args[i]
        if arg in ("-h", "--help"):
            print_help(app_name)
            sys.exit(0)
