        elif rl == 2: c = 8
        elif rl == 3 or rl == 4: c = 7
        else: c = 15
    elif gl >= rl and bl >= rl and abs(gl - bl) <= 1:
        c = 14 if is_bright else 6 # Cyan
    elif rl >= gl and gl >= bl and abs(rl - gl) <= 1:
        c = 11 if is_bright else 3 # Yellow
    elif rl >= gl and bl >= gl and abs(rl - bl) <= 1:
