    elif rl >= gl and rl >= bl:
        c = 9 if is_bright else 1 # Red
    elif gl >= rl and gl >= bl:
        c = 10 if is_bright else 2 # Green
    else:
        c = 12 if is_bright else 4 # Blue

    return c

