def get_chroma_tokens(code, plex):
    raw_tokens = plex.get_tokens(code)
    tokens = []
    for token_type, value in raw_tokens:
        if not value:
            continue
        t_str = str(token_type)
        if t_str.startswith("Token."):
            t_name = t_str[6:].replace(".", "")
        else:
            t_name = t_str.replace(".", "")
        if t_name == "TextWhitespace":
            t_name = "Text"
        if tokens and tokens[-1][0] == t_name:
            tokens[-1] = (t_name, tokens[-1][1] + value)
        else:
            tokens.append((t_name, value))
    return tokens

def parse_highlight_lines(s):
    lines = set()
    if not s:
        return lines
    for part in s.split(","):
        part = part.strip()
        if ":" in part:
            try:
                start, end = part.split(":", 1)
                lines.update(range(int(start), int(end) + 1))
            except ValueError:
                pass
        elif part:
            try:
                lines.add(int(part))
            except ValueError:
