# Build 256 Color Palette
def get_256_palette():
    palette = []
    ansi16 = [
        (0,0,0), (128,0,0), (0,128,0), (128,128,0), (0,0,128), (128,0,128), (0,128,128), (192,192,192),
        (128,128,128), (255,0,0), (0,255,0), (255,255,0), (0,0,255), (255,0,255), (0,255,255), (255,255,255)
    ]
    palette.extend(ansi16)
    vals = [0, 95, 135, 175, 215, 255]
    for r in vals:
        for g in vals:
            for b in vals:
                palette.append((r, g, b))
    for i in range(24):
        v = 8 + i * 10
        palette.append((v, v, v))
    return palette

PALETTE_256 = get_256_palette()

def hex_to_rgb(h):
    if not h:
        return None
    h = h.lstrip("#")
    if len(h) == 3:
        h = "".join(c*2 for c in h)
    return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

def rgb_to_256(r, g, b):
    best_i = 0
    best_dist = 100000000
    for i in range(232):
        pr, pg, pb = PALETTE_256[i]
        d = (r - pr)**2 + (g - pg)**2 + (b - pb)**2
        if d < best_dist:
            best_dist = d
            best_i = i
    return best_i

def rgb_to_16_smart(r, g, b):
    vals = [0, 95, 135, 175, 215, 255]
    def closest_level(v):
        return min(range(6), key=lambda i: abs(v - vals[i]))

    rl, gl, bl = closest_level(r), closest_level(g), closest_level(b)
    is_bright = max(rl, gl, bl) >= 3

    if rl == gl == bl:
        if rl < 2: return 0
        elif rl == 2: return 8
        elif rl in (3, 4): return 7
        else: return 15
    if gl >= rl and bl >= rl and abs(gl - bl) <= 1:
        return 14 if is_bright else 6
    if rl >= bl and gl >= bl and abs(rl - gl) <= 1:
        return 11 if is_bright else 3
    if rl >= gl and bl >= gl and abs(rl - gl) <= 1:
        return 13 if is_bright else 5
    if rl >= gl and rl >= bl:
        return 9 if is_bright else 1
    if gl >= rl and gl >= bl:
        return 10 if is_bright else 2
    return 12 if is_bright else 4

def rgb_to_16(r, g, b):
