    for part in s.split(","):
        part = part.strip()
        if ":" in part:
            try:
                start, end = part.split(":", 1)
                lines.update(range(int(start), int(end) + 1))
            except ValueError:
                pass
        elif part:
            try:
                lines.add(int(part))
            except ValueError:
                pass
    return lines

