                        codes.append(f"48;2;{r};{g};{b}")

                prefix_seq = "".join(f"\x1b[{c}m" for c in codes)
                if val.endswith("\n"):
                    val_clean = val[:-1]
                    out_parts.append(f"{prefix_seq}{val_clean}\x1b[0m\n")
